/**
 * dsh-market — browser half.
 *
 * One right-Sidebar tab ("插件市场") that shows what this Harness can install:
 *
 *   * 官方随包 — the plugin bundles that ship inside this dsh install and are
 *     not selected by the profile yet. One click installs by name.
 *   * 在线 — npm search hits for the configured keyword, each with its
 *     publisher and version.
 *   * 已安装 — `pluginManager.listBundles()`/`listPlugins()` rows with
 *     启用 / 停用 / 卸载.
 *
 * Every mutation goes through `ctx.remote.pluginManager` — the same Remote API
 * the shipped Plugins panel uses. This page never writes a profile file and
 * never runs a package manager itself: it is a catalogue in front of the one
 * supported install path, which is why a failure here shows the manager's own
 * diagnostic instead of inventing one.
 */
window.__ModuleLoader__.load({
  id: '@local/dsh-market',
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    /** This package's tab-type id; also the keyed seat the body registers under. */
    const ID = '@local/dsh-market';
    /** The tab kind recorded in the Session's sidebar state. */
    const KIND = 'dsh-market';
    /** This package's copy namespace. */
    const NS = 'dshMarket';
    /** The host half's catalogue route. */
    const CATALOG_PATH = '/dsh-market/catalog';

    /** Simplified Chinese dictionary and key-set source of truth. */
    const zh = {
      'type.label': '插件市场',
      'guide.title': '插件市场',
      'guide.description': '看这个 Harness 能装什么插件，一键装、启用或停用。',
      'action.refresh': '刷新',
      'action.install': '安装',
      'action.enable': '启用',
      'action.disable': '停用',
      'action.remove': '卸载',
      'state.loading': '正在读取目录…',
      'state.error': '目录读取失败',
      'state.empty': '没有可安装的插件',
      'section.official': '官方随包（本机已带，装上即用）',
      'section.official.hint': '这些 bundle 随 dsh 安装一起发布，安装只是把它的补丁挂进 profile。',
      'section.online': '在线目录（npm）',
      'section.online.hint': '按关键词在 npm 上搜索到的插件；安装需要网络。',
      'section.installed': '已安装',
      'section.installed.hint': '来自 pluginManager：bundle 与它贡献的插件行。',
      'badge.installed': '已安装',
      'badge.enabled': '已启用',
      'badge.disabled': '已停用',
      'badge.failed': '加载失败',
      'badge.optional': '可选',
      'busy.installing': '正在安装…',
      'busy.applying': '正在应用…',
      'note.installDone': '已安装 {name}。',
      'note.installRestart': '已安装 {name}，需要重启 dsh web 才会加载新的 JavaScript 模块。',
      'note.enableDone': '已启用 {name}。',
      'note.disableDone': '已停用 {name}。',
      'note.removeDone': '已卸载 {name}。',
      'note.noPluginManager': '这个 profile 没有 pluginManager 远端，无法安装或启停。',
      'error.prefix': '失败：',
      'meta.publisher': '发布者',
      'meta.source.official': '随包',
      'meta.source.npm': 'npm',
      'meta.installedAt': 'profile',
    };

    /** English dictionary; every key above must appear here too. */
    const en = {
      'type.label': 'Plugin market',
      'guide.title': 'Plugin market',
      'guide.description': 'What this Harness can install — install, enable or disable in one click.',
      'action.refresh': 'Refresh',
      'action.install': 'Install',
      'action.enable': 'Enable',
      'action.disable': 'Disable',
      'action.remove': 'Remove',
      'state.loading': 'Reading the catalogue…',
      'state.error': 'Could not read the catalogue',
      'state.empty': 'Nothing to install',
      'section.official': 'Ships with dsh (already on this device)',
      'section.official.hint': 'Bundles published with this dsh install; installing mounts their patch into the profile.',
      'section.online': 'Online catalogue (npm)',
      'section.online.hint': 'Plugins found on npm by keyword; installing needs the network.',
      'section.installed': 'Installed',
      'section.installed.hint': 'From pluginManager: bundles and the plugin rows they contribute.',
      'badge.installed': 'installed',
      'badge.enabled': 'enabled',
      'badge.disabled': 'disabled',
      'badge.failed': 'failed to load',
      'badge.optional': 'optional',
      'busy.installing': 'Installing…',
      'busy.applying': 'Applying…',
      'note.installDone': 'Installed {name}.',
      'note.installRestart': 'Installed {name}; restart dsh web to load the new JavaScript module generation.',
      'note.enableDone': 'Enabled {name}.',
      'note.disableDone': 'Disabled {name}.',
      'note.removeDone': 'Removed {name}.',
      'note.noPluginManager': 'This profile has no pluginManager remote: install and enable/disable are unavailable.',
      'error.prefix': 'Failed: ',
      'meta.publisher': 'publisher',
      'meta.source.official': 'bundled',
      'meta.source.npm': 'npm',
      'meta.installedAt': 'profile',
    };

    /**
     * The payload out of a Remote answer.
     *
     * Measured on a real instance: `ctx.remote.pluginManager.listBundles()`
     * resolves to `{ ok: true, value: [...] }`, and a failed call to
     * `{ ok: false, error: { code, diagnostic } }`. A page that maps the
     * envelope itself renders nothing and says nothing, which is exactly what
     * happened before this unwrap existed.
     */
    function unwrap(answer) {
      if (answer === null || typeof answer !== 'object' || Array.isArray(answer) || !('ok' in answer)) return answer;
      if (answer.ok === false) {
        const error = new Error(messageOf(answer.error ?? answer));
        error.code = answer.error?.code;
        throw error;
      }
      return answer.value;
    }

    /** The rows out of a list answer that may be an array or a keyed object. */
    function rowsOf(value, key) {
      const payload = unwrap(value);
      if (Array.isArray(payload)) return payload;
      const inner = payload?.[key];
      if (Array.isArray(inner)) return inner;
      return [];
    }

    /**
     * One string out of a possibly localised text field.
     *
     * Bundle and plugin metadata carry `{ en, zh }` objects as well as plain
     * strings (the manager's own schema allows both). Passing one straight into a
     * React child throws error #31 and — before the boundary existed — left an
     * empty pane. Everything that reaches the DOM goes through here.
     */
    function textOf(value, fallback = '') {
      if (typeof value === 'string') return value;
      if (typeof value === 'number' && Number.isFinite(value)) return String(value);
      if (value !== null && typeof value === 'object') {
        for (const candidate of [value.zh, value.en, ...Object.values(value)]) {
          if (typeof candidate === 'string') return candidate;
        }
      }
      return fallback;
    }

    /** One readable sentence out of whatever the manager threw or returned. */
    function messageOf(cause) {
      if (cause === null || cause === undefined) return 'unknown error';
      if (typeof cause === 'string') return cause;
      if (typeof cause.message === 'string' && cause.message.length > 0) return cause.message;
      const code = cause.code ?? cause.error?.code;
      const diagnostic = cause.diagnostic ?? cause.error?.diagnostic;
      if (typeof diagnostic === 'string' && diagnostic.length > 0) return code ? `${diagnostic} (${String(code)})` : diagnostic;
      try {
        return JSON.stringify(cause).slice(0, 300);
      } catch {
        return String(cause);
      }
    }

    const css = {
      root: { display: 'flex', flexDirection: 'column', gap: '10px', padding: '10px', height: '100%', overflow: 'auto', fontSize: '13px', color: 'var(--ink, #222)' },
      bar: { display: 'flex', alignItems: 'center', gap: '8px' },
      section: { display: 'flex', flexDirection: 'column', gap: '6px', border: '1px solid var(--line, #e3e3e3)', borderRadius: '8px', padding: '8px' },
      sectionTitle: { fontWeight: 600, fontSize: '13px' },
      hint: { opacity: 0.7, fontSize: '12px', lineHeight: 1.4 },
      row: { display: 'flex', alignItems: 'flex-start', gap: '8px', padding: '6px 0', borderTop: '1px solid var(--line, #eee)' },
      grow: { flex: 1, minWidth: 0 },
      name: { fontFamily: 'ui-monospace, monospace', fontSize: '12px', wordBreak: 'break-all' },
      desc: { opacity: 0.75, fontSize: '12px', lineHeight: 1.4, marginTop: '2px' },
      badges: { display: 'flex', gap: '4px', flexWrap: 'wrap', marginTop: '3px' },
      badge: { fontSize: '11px', border: '1px solid var(--line, #ddd)', borderRadius: '999px', padding: '0 6px', opacity: 0.85 },
      actions: { display: 'flex', flexDirection: 'column', gap: '4px' },
      button: { fontSize: '12px', padding: '3px 8px', borderRadius: '6px', border: '1px solid var(--line, #ccc)', background: 'transparent', color: 'inherit', cursor: 'pointer' },
      note: { fontSize: '12px', padding: '6px 8px', borderRadius: '6px', border: '1px solid var(--line, #ddd)' },
      error: { fontSize: '12px', padding: '6px 8px', borderRadius: '6px', border: '1px solid #d66', color: '#b22' },
    };

    /**
     * Catches a render failure inside this pane and shows it.
     *
     * Without it React unmounts the pane and the user sees an empty tab, which
     * is the least debuggable outcome possible — measured on a real instance.
     */
    class Boundary extends React.Component {
      constructor(props) {
        super(props);
        this.state = { error: null };
      }
      static getDerivedStateFromError(error) {
        return { error };
      }
      render() {
        if (this.state.error !== null) {
          return h('div', { style: css.error }, `${this.props.t('state.error')}: ${messageOf(this.state.error)}`);
        }
        return this.props.children;
      }
    }

    /** A badge carrying one short state word. */
    function Badge(props) {
      return h('span', { style: css.badge, title: props.title ?? '' }, props.text);
    }

    /** One catalogue row: identity on the left, actions on the right. */
    function Entry(props) {
      const entry = props.entry;
      const [busy, setBusy] = React.useState(false);
      const meta = [];
      if (entry.source === 'npm' && entry.publisher) meta.push(`${props.t('meta.publisher')}: ${entry.publisher}`);
      if (entry.version) meta.push(entry.version);
      return h('div', { style: css.row }, [
        h('div', { key: 'body', style: css.grow }, [
          h('div', { key: 'name', style: css.name }, textOf(entry.name, '(unnamed)')),
          textOf(entry.description) ? h('div', { key: 'desc', style: css.desc }, textOf(entry.description)) : null,
          h('div', { key: 'badges', style: css.badges }, [
            h(Badge, { key: 'source', text: entry.source === 'npm' ? props.t('meta.source.npm') : props.t('meta.source.official') }),
            entry.installed ? h(Badge, { key: 'installed', text: props.t('badge.installed') }) : null,
            ...meta.map((text, index) => h(Badge, { key: `meta${String(index)}`, text })),
          ]),
        ]),
        h('div', { key: 'actions', style: css.actions }, props.actions.map((action) =>
          h('button', {
            key: action.label,
            style: css.button,
            disabled: busy || action.disabled === true,
            title: action.title ?? '',
            onClick: async () => {
              setBusy(true);
              try {
                await action.run();
              } finally {
                setBusy(false);
              }
            },
          }, busy ? props.t('busy.applying') : action.label))),
      ]);
    }

    /** The whole page: catalogue + installed state, and every action. */
    function Market(props) {
      const t = typeof props.t === 'function' ? props.t : (key, params) => {
        const template = zh[key] ?? key;
        return params === undefined ? template : template.replace(/\{(\w+)\}/gu, (_, name) => String(params[name] ?? ''));
      };
      const market = props.market;
      const [state, setState] = React.useState({ phase: 'loading', catalog: null, bundles: [], plugins: [], error: null, note: null });

      const read = React.useCallback(async (refresh) => {
        const next = { phase: 'ready' };
        try {
          const response = await fetch(refresh ? `${CATALOG_PATH}?refresh=1` : CATALOG_PATH, { cache: 'no-store' });
          next.catalog = await response.json();
        } catch (cause) {
          next.phase = 'error';
          next.error = messageOf(cause);
        }
        if (market.available) {
          try {
            const [bundles, plugins] = await Promise.all([market.listBundles(), market.listPlugins()]);
            // The Remote may answer with the array itself or wrapped in a keyed
            // object, and a page that maps over a non-array unmounts silently —
            // measured on a real instance, so both shapes are accepted here.
            next.bundles = rowsOf(bundles, 'bundles');
            next.plugins = rowsOf(plugins, 'plugins');
          } catch (cause) {
            next.error = `${t('error.prefix')}${messageOf(cause)}`;
            window.__dshMarketLastError = messageOf(cause);
          }
        }
        setState((previous) => ({ ...previous, ...next, error: next.error ?? null }));
      }, [market, t]);

      React.useEffect(() => { void read(false); }, [read]);

      const act = React.useCallback(async (run, noteKey, name) => {
        try {
          const result = await run();
          const note = result?.restartRequired === true ? t('note.installRestart', { name }) : t(noteKey, { name });
          setState((previous) => ({ ...previous, note, error: null }));
        } catch (cause) {
          setState((previous) => ({ ...previous, note: null, error: `${t('error.prefix')}${messageOf(cause)}` }));
        }
        await read(false);
      }, [read, t]);

      if (state.phase === 'loading') return h('div', { style: css.root }, t('state.loading'));

      const catalog = state.catalog ?? { official: [], online: [], errors: {} };
      const installable = (catalog.official ?? []).filter((entry) => entry.installed !== true);
      const installed = new Set((catalog.installed ?? []).map((name) => String(name)));
      const bundles = state.bundles ?? [];
      const plugins = state.plugins ?? [];

      const sections = [];

      sections.push(h('div', { key: 'official', style: css.section }, [
        h('div', { key: 'title', style: css.sectionTitle }, `${t('section.official')} · ${String(installable.length)}`),
        h('div', { key: 'hint', style: css.hint }, t('section.official.hint')),
        installable.length === 0
          ? h('div', { key: 'empty', style: css.hint }, t('state.empty'))
          : installable.map((entry) => h(Entry, {
            key: entry.name,
            entry,
            t,
            actions: [{
              label: t('action.install'),
              disabled: !market.available,
              run: () => act(() => market.install(entry.name), 'note.installDone', entry.name),
            }],
          })),
      ]));

      sections.push(h('div', { key: 'online', style: css.section }, [
        h('div', { key: 'title', style: css.sectionTitle }, `${t('section.online')} · ${String((catalog.online ?? []).length)}`),
        h('div', { key: 'hint', style: css.hint }, t('section.online.hint')),
        catalog.errors?.online
          ? h('div', { key: 'err', style: css.error }, `${t('error.prefix')}${catalog.errors.online}`)
          : (catalog.online ?? []).map((entry) => h(Entry, {
            key: entry.name,
            entry,
            t,
            actions: [{
              label: t('action.install'),
              disabled: !market.available || installed.has(entry.name),
              run: () => act(() => market.install(entry.name), 'note.installDone', entry.name),
            }],
          })),
      ]));

      sections.push(h('div', { key: 'installed', style: css.section }, [
        h('div', { key: 'title', style: css.sectionTitle }, `${t('section.installed')} · ${String(bundles.length)}`),
        h('div', { key: 'hint', style: css.hint }, t('section.installed.hint')),
        bundles.length === 0 ? h('div', { key: 'empty', style: css.hint }, t('state.empty')) : bundles.map((bundle) => h(Entry, {
          key: `bundle:${bundle.name}`,
          t,
          entry: {
            name: bundle.name,
            version: bundle.version ?? '',
            description: textOf(bundle.meta?.description, textOf(bundle.description)),
            source: 'official',
            installed: true,
          },
          actions: [
            {
              label: bundle.enabled ? t('action.disable') : t('action.enable'),
              disabled: !market.available || bundle.removable === false && bundle.enabled === true,
              run: () => act(() => market.setBundleEnabled(bundle.name, !bundle.enabled), bundle.enabled ? 'note.disableDone' : 'note.enableDone', bundle.name),
            },
            {
              label: t('action.remove'),
              disabled: !market.available || bundle.removable === false,
              title: bundle.readOnlyReason ?? '',
              run: () => act(() => market.remove(bundle.name), 'note.removeDone', bundle.name),
            },
          ],
        })),
        ...plugins.filter((plugin) => plugin.patchId !== undefined).map((plugin) => h(Entry, {
          key: `plugin:${String(plugin.entryId)}`,
          t,
          entry: {
            name: String(plugin.entryId),
            version: '',
            description: textOf(plugin.meta?.description),
            source: 'official',
            installed: true,
          },
          actions: [{
            label: plugin.enabled ? t('action.disable') : t('action.enable'),
            disabled: !market.available,
            run: () => act(() => market.setPluginEnabled(plugin.entryId, !plugin.enabled), plugin.enabled ? 'note.disableDone' : 'note.enableDone', String(plugin.entryId)),
          }],
        })),
      ]));

      return h('div', { style: css.root }, [
        h('div', { key: 'bar', style: css.bar }, [
          h('button', {
            key: 'refresh',
            style: css.button,
            onClick: () => { setState((previous) => ({ ...previous, phase: 'loading' })); void read(true); },
          }, t('action.refresh')),
          catalog.generatedAt ? h('span', { key: 'at', style: css.hint }, new Date(catalog.generatedAt).toLocaleTimeString()) : null,
          catalog.cached === true ? h('span', { key: 'cached', style: css.hint }, 'cache') : null,
        ]),
        !market.available ? h('div', { key: 'nopm', style: css.error }, t('note.noPluginManager')) : null,
        state.error ? h('div', { key: 'error', style: css.error }, state.error) : null,
        state.note ? h('div', { key: 'note', style: css.note }, state.note) : null,
        ...sections,
      ]);
    }

    return {
      // Both entries are required, and the live GUI proved it: without `remote`
      // the client context has no gateway at all, and without the *namespace*
      // `remote.pluginManager` the gateway refuses that name — the page renders
      // with every action disabled (measured on a real instance, then fixed here).
      /** Pure helpers, exported for the offline tests (the pane itself is a component). */
      __internals: { textOf, messageOf, rowsOf, unwrap },
      inject: ['slots', 'locale', 'sidebarRightTabs', 'remote', 'remote.pluginManager'],
      /**
       * Register the tab type, its copy, and its body seat. The Remote API is
       * wrapped once here, so the page never reaches for a service and stays a
       * plain component.
       * @param ctx - Client root context carrying slots, copy, tabs and the Remote gateway.
       */
      apply(ctx) {
        const t = ctx.locale.bind(NS);
        // A profile without the plugin manager must still render the catalogue,
        // so a missing (or throwing) namespace is a state, not a crash.
        let manager;
        try {
          manager = ctx.remote?.pluginManager;
        } catch {
          manager = undefined;
        }
        // `await` first: unwrap() must see the resolved envelope, not a Promise.
        const call = async (method, ...args) => unwrap(await manager[method](...args));
        const market = {
          available: manager !== undefined && manager !== null,
          listBundles: () => manager.listBundles(),
          listPlugins: () => manager.listPlugins(),
          install: (name) => call('installBundle', name, {}),
          setBundleEnabled: (name, enabled) => call('setBundleEnabled', name, enabled),
          setPluginEnabled: (entryId, enabled) => call('setPluginEnabled', entryId, enabled),
          remove: (name) => call('removeBundle', name),
        };
        ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-market: dictionaries');
        ctx.effect(() => ctx.sidebarRightTabs.register({
          id: ID,
          kind: KIND,
          title: () => t('type.label'),
          guide: [{
            id: 'market',
            order: 30,
            title: () => t('guide.title'),
            description: () => t('guide.description'),
          }],
        }), 'dsh-market: type');
        ctx.effect(() => ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({
          name: 'sidebar.right.pane.tab',
          key: ID,
          locale: NS,
        }, (props) => h(Boundary, { t: props.t }, h(Market, { ...props, market })))), 'dsh-market: body');
      },
    };
  },
});
